// Generates src/icons.generated.ts from Phosphor Icons (MIT), the icon set used by the Argus HUD.
//
//   node tools/make-icons.mjs [path to phosphor-svelte/lib]
//
// Only the icons listed in NAMES are taken, in three weights (regular, duotone, fill), as plain SVG shapes:
// the console ships no icon library and no network request for icons. Run it only when NAMES changes; the
// generated file is committed. The default source is the Argus HUD's copy of phosphor-svelte.
import { readFileSync, writeFileSync } from "node:fs";

const SOURCE =
  process.argv[2] ?? process.env.PHOSPHOR_LIB ?? "C:/ARGUS/argus-os/hud-v2/node_modules/phosphor-svelte/lib";

const NAMES = [
  // navigation
  "Gauge", "MagnifyingGlass", "Pulse", "ShieldCheck", "ListChecks", "Scroll", "SignOut", "Key",
  // verdicts
  "Skull", "Warning", "CheckCircle", "Question", "WarningOctagon", "SealCheck", "ShieldWarning", "ShieldSlash",
  // artifacts
  "Link", "EnvelopeSimple", "File", "FilePdf", "FileZip", "Paperclip", "Globe", "QrCode", "Image", "FileText",
  "ArrowsSplit", "ArrowBendUpRight", "Detective", "Fish", "Fingerprint", "LockKey", "LockOpen", "Hash",
  "TextAa", "Cloud", "UserCircle", "Lightning", "Target", "Eye", "EyeSlash", "Code", "Tag",
  // actions and states
  "ArrowRight", "ArrowLeft", "CaretDown", "CaretRight", "X", "Check", "Copy", "UploadSimple", "CloudArrowUp",
  "CircleNotch", "Clock", "ClockCounterClockwise", "ArrowsClockwise", "ArrowUUpLeft", "Vault", "Prohibit",
  "Info", "Bell", "Funnel", "Trash", "Plus", "Sparkle", "Binoculars", "Flask", "TreeStructure", "Cpu",
  "HardDrives", "Plugs", "EnvelopeOpen", "Crosshair", "ListMagnifyingGlass", "Stamp", "Hourglass", "CircleDashed",
];
const WEIGHTS = ["regular", "duotone", "fill"];
const SHAPES = /<(path|circle|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/>/g;
const ATTR = /([a-zA-Z:-]+)="([^"]*)"/g;

function shapes(markup) {
  const out = [];
  for (const m of markup.matchAll(SHAPES)) {
    const attrs = {};
    for (const a of m[2].matchAll(ATTR)) attrs[a[1]] = a[2];
    out.push([m[1], attrs]);
  }
  return out;
}

/** The markup of each weight inside {#if weight === "bold"} ... {:else if ...} ... {:else} ... {/if}. */
function byWeight(source) {
  const body = source.slice(source.indexOf('<rect width="256" height="256" fill="none" />'));
  const parts = {};
  const re = /\{#if weight === "(\w+)"\}|\{:else if weight === "(\w+)"\}|\{:else\}|\{\/if\}/g;
  let name = null;
  let from = 0;
  for (const m of body.matchAll(re)) {
    if (name !== null) parts[name] = body.slice(from, m.index);
    name = m[1] ?? m[2] ?? null; // the final {:else} only prints an "unsupported weight" error: ignored
    from = m.index + m[0].length;
  }
  return parts;
}

const missing = [];
const table = {};
for (const name of NAMES) {
  let source;
  try {
    source = readFileSync(`${SOURCE}/${name}.svelte`, "utf8");
  } catch {
    missing.push(name);
    continue;
  }
  const parts = byWeight(source);
  table[name] = Object.fromEntries(WEIGHTS.map((w) => [w, shapes(parts[w] ?? "")]));
  for (const w of WEIGHTS) if (table[name][w].length === 0) throw new Error(`${name}: no shapes for weight ${w}`);
}
if (missing.length) {
  console.error("missing in the source set: " + missing.join(", "));
  process.exit(1);
}

const lines = [
  "// GENERATED by tools/make-icons.mjs from Phosphor Icons (MIT, https://phosphoricons.com). Do not edit by hand.",
  "// The icon set of the Argus HUD, reduced to the icons Lynceus uses. See THIRD_PARTY.md.",
  'export type Weight = "regular" | "duotone" | "fill";',
  'export type Shape = readonly [tag: "path" | "circle" | "rect" | "line" | "polyline" | "polygon" | "ellipse", attrs: Readonly<Record<string, string>>];',
  "export const ICONS = {",
  ...Object.entries(table).map(([name, w]) => `  ${name}: ${JSON.stringify(w)},`),
  "} as const satisfies Record<string, Record<Weight, readonly Shape[]>>;",
  "export type IconName = keyof typeof ICONS;",
  "",
];
writeFileSync(new URL("../src/icons.generated.ts", import.meta.url), lines.join("\n"));
console.log(`wrote ${Object.keys(table).length} icons x ${WEIGHTS.length} weights`);
